export const WEATHER=Object.freeze({clear:{name:'Clear skies',top:'#4e9bd0',horizon:'#d6e8df',fog:'#bdd7d5',sun:2.5,ambient:1.05,start:210,end:720,cloud:.18,rain:0,wind:1},cloudy:{name:'Passing clouds',top:'#72a2bc',horizon:'#d6dfd7',fog:'#c0d0c6',sun:1.8,ambient:1.15,start:180,end:620,cloud:.7,rain:0,wind:1.8},rain:{name:'Rain showers',top:'#637d91',horizon:'#aabdbb',fog:'#9fb3ae',sun:.7,ambient:1.1,start:100,end:390,cloud:1,rain:1,wind:2.5},storm:{name:'Storm front',top:'#344858',horizon:'#6e8589',fog:'#758d8c',sun:.35,ambient:.85,start:65,end:260,cloud:1,rain:1,wind:5},mist:{name:'Morning mist',top:'#9eb8bd',horizon:'#d4ded0',fog:'#c5d3c4',sun:1.1,ambient:1.15,start:40,end:240,cloud:.4,rain:0,wind:.5}});
export function ensureWeather(s){if(!s.weather)s.weather={mode:'auto',seed:1927};if(!WEATHER[s.weather.mode]&&s.weather.mode!=='auto')s.weather.mode='auto';return s.weather;}
export function weatherType(s){const w=ensureWeather(s);if(w.mode!=='auto')return w.mode;let n=Math.imul((s.day||1)^w.seed,0x45d9f3b);n=Math.imul(n^(n>>>16),0x45d9f3b);const v=((n^(n>>>16))>>>0)%100;return v<40?'clear':v<70?'cloudy':v<88?'rain':v<98?'mist':'storm';}
export function selectWeather(s,mode){if(mode!=='auto'&&!WEATHER[mode])throw Error('Choose a valid weather pattern.');ensureWeather(s).mode=mode;return mode;}
